<?php
declare(strict_types=1);
require __DIR__ . '/app/bootstrap.php';
$admin = require_admin();
$pdo = db();
$counts = [
  'users'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE status='active'")->fetchColumn(),
  'deals'=>(int)$pdo->query("SELECT COUNT(*) FROM deals WHERE status IN ('awaiting_payment','funding','funded','in_progress','delivered','in_review','disputed')")->fetchColumn(),
  'disputes'=>(int)$pdo->query("SELECT COUNT(*) FROM deals WHERE status='disputed'")->fetchColumn(),
  'reports'=>(int)$pdo->query("SELECT COUNT(*) FROM safety_reports WHERE status IN ('new','reviewing')")->fetchColumn(),
];
$users=$pdo->query("SELECT id,name,email,role,status,created_at FROM users ORDER BY created_at DESC LIMIT 100")->fetchAll();
$deals=$pdo->query("SELECT d.id,d.public_id,d.title,d.currency,d.amount_minor,d.fee_minor,d.status,d.created_at,u.name AS buyer FROM deals d JOIN users u ON u.id=d.buyer_id ORDER BY d.created_at DESC LIMIT 100")->fetchAll();
$reports=$pdo->query("SELECT r.id,r.category,r.details,r.status,r.created_at,u.name AS reporter FROM safety_reports r LEFT JOIN users u ON u.id=r.reporter_id ORDER BY r.created_at DESC LIMIT 100")->fetchAll();
$payments=$pdo->query("SELECT p.id,p.provider,p.provider_reference,p.amount_minor,p.currency,p.status,p.created_at,d.public_id FROM payment_intents p JOIN deals d ON d.id=p.deal_id ORDER BY p.created_at DESC LIMIT 100")->fetchAll();
$cryptoPending=$pdo->query("SELECT p.id,p.network,p.provider_reference,p.amount_minor,p.created_at,JSON_UNQUOTE(JSON_EXTRACT(p.provider_payload,'$.customer_tx_hash')) AS customer_tx_hash,d.public_id,d.title FROM payment_intents p JOIN deals d ON d.id=p.deal_id WHERE p.provider='crypto' AND p.status='pending' ORDER BY p.created_at ASC LIMIT 100")->fetchAll();
