.admin{max-width:1320px;margin:auto;padding:30px}.admin-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.admin-head h1{font:700 25px var(--display);margin:7px 0}.admin-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.admin-stat{padding:16px;background:white;border:1px solid #e9ede8;border-radius:9px}.admin-stat span{font-size:10px;color:#87928a}.admin-stat b{display:block;font:700 22px var(--display);margin-top:7px}.admin-tabs{display:flex;gap:7px;overflow:auto;margin:14px 0}.admin-tabs button{padding:9px 12px;border:1px solid #e6ebe6;border-radius:6px;background:white;color:#6d7a71;font-size:10px;white-space:nowrap}.admin-tabs button.active{background:#eaf3ec;color:#315f43}.admin-section{display:none}.admin-section.active{display:block}.admin-table{background:white;border:1px solid #e8ece7;border-radius:9px;overflow:auto}.admin-table table{border-collapse:collapse;width:100%;min-width:740px}.admin-table th,.admin-table td{text-align:left;padding:11px 12px;border-bottom:1px solid #eff1ee;font-size:10px;vertical-align:top}.admin-table th{color:#8d9890;font-size:8px;letter-spacing:.1em}.admin-table td{color:#526057}.admin-table td b{color:#2f4035}.admin-table form{display:flex;gap:5px}.admin-table select{border:1px solid #dfe6df;border-radius:5px;padding:5px;font-size:9px}.admin-table form button{border:0;background:#eaf3ec;color:#346147;border-radius:5px;padding:6px 8px;font-size:9px;font-weight:700}.admin-note{padding:13px;background:#fbf5e8;color:#8a744d;border-radius:7px;font-size:10px;line-height:1.5;margin:14px 0}.admin-actions{display:flex;gap:10px;align-items:center}.admin-user{font-size:10px;color:#79867e}.admin-table td.details{max-width:360px;white-space:normal;line-height:1.5}.back-link{color:#38664b;font-weight:700;text-decoration:none;font-size:11px}@media(max-width:800px){.admin{padding:20px 13px}.admin-stats{grid-template-columns:repeat(2,1fr)}}
