<section class="admin-stats"><div class="admin-stat"><span>Active users</span><b><?=$counts['users']?></b></div><div class="admin-stat"><span>Open deals</span><b><?=$counts['deals']?></b></div><div class="admin-stat"><span>Disputes requiring review</span><b><?=$counts['disputes']?></b></div><div class="admin-stat"><span>Safety reports to review</span><b><?=$counts['reports']?></b></div></section>
<div class="admin-note"><b>HashPay M-Pesa collection is wired for verified deal payments.</b> The payment page supports hosted M-Pesa and manual USDT deposits. Admins must verify each crypto transaction hash on-chain before confirming it; this console does not trigger seller payouts or refunds. Configure your live HashPay channel and signing secret before use.</div>
<?php if($cryptoPending):?><section style="margin:18px 0"><h2>USDT deposits awaiting manual verification</h2><p>Check the transfer on the matching network and verify the receiving address and exact amount before marking the deal funded.</p><div class="admin-table"><table><thead><tr><th>DEAL</th><th>NETWORK</th><th>AMOUNT</th><th>REFERENCE</th><th>VERIFIED TRANSACTION HASH</th></tr></thead><tbody><?php foreach($cryptoPending as $cp):?><tr><td><b><?=e($cp['title'])?></b><br><?=e($cp['public_id'])?></td><td><?=e(strtoupper($cp['network']))?></td><td>USDT <?=number_format(((int)$cp['amount_minor'])/100,2)?></td><td><?=e($cp['provider_reference'])?></td><td><form method="post" action="admin-action.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="crypto_confirm"><input type="hidden" name="id" value="<?=(int)$cp['id']?>"><input name="tx_hash" required minlength="64" maxlength="64" pattern="[A-Fa-f0-9]{64}" value="<?=e($cp['customer_tx_hash']??'')?>" placeholder="64-character transaction hash"><button type="submit">Confirm deposit</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><nav class="admin-tabs"><button class="active" data-admin-tab="deals">Deals &amp; disputes (<?=count($deals)?>)</button><button data-admin-tab="payments">Payment records (<?=count($payments)?>)</button><button data-admin-tab="users">Accounts (<?=count($users)?>)</button><button data-admin-tab="reports">Safety reports (<?=count($reports)?>)</button></nav>
<section class="admin-section active" id="admin-deals"><div class="admin-table"><table><thead><tr><th>DEAL</th><th>BUYER</th><th>AMOUNT</th><th>STATUS</th><th>CREATED</th></tr></thead><tbody><?php foreach($deals as $d):?><tr><td><b><?=e($d['title'])?></b><br><small><?=e($d['public_id'])?></small></td><td><?=e($d['buyer'])?></td><td><?=e($d['currency'])?> <?=number_format(((int)$d['amount_minor'])/100,2)?><br><small>Buyer fee: <?=e($d['currency'])?> <?=number_format(((int)$d['fee_minor'])/100,2)?></small></td><td><?=e($d['status'])?></td><td><?=e($d['created_at'])?></td></tr><?php endforeach;?><?php if(!$deals):?><tr><td colspan="5">No deals have been created.</td></tr><?php endif;?></tbody></table></div></section>
<section class="admin-section" id="admin-payments"><div class="admin-table"><table><thead><tr><th>DEAL</th><th>PROVIDER</th><th>REFERENCE</th><th>AMOUNT</th><th>STATUS</th><th>CREATED</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=e($p['public_id'])?></td><td><?=e($p['provider'])?></td><td><?=e($p['provider_reference']??'—')?></td><td><?=e($p['currency'])?> <?=number_format(((int)$p['amount_minor'])/100,2)?></td><td><?=e($p['status'])?></td><td><?=e($p['created_at'])?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="6">No payment provider is connected; no live payment records yet.</td></tr><?php endif;?></tbody></table></div></section>
<section class="admin-section" id="admin-users"><div class="admin-table"><table><thead><tr><th>ACCOUNT</th><th>EMAIL</th><th>ROLE</th><th>STATUS</th><th>CREATED</th><th>CHANGE STATUS</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><b><?=e($u['name'])?></b></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['status'])?></td><td><?=e($u['created_at'])?></td><td><form method="post" action="admin-action.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="user_status"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><select name="status"><option value="active">Active</option><option value="suspended">Suspend</option><option value="closed">Close</option></select><button>Save</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="admin-section" id="admin-reports"><div class="admin-table"><table><thead><tr><th>REPORT</th><th>DETAILS</th><th>REPORTER</th><th>STATUS</th><th>UPDATE</th></tr></thead><tbody><?php foreach($reports as $r):?><tr><td><b><?=e($r['category'])?></b><br><small>#<?=(int)$r['id']?> · <?=e($r['created_at'])?></small></td><td class="details"><?=nl2br(e($r['details']))?></td><td><?=e($r['reporter']??'Guest')?></td><td><?=e($r['status'])?></td><td><form method="post" action="admin-action.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="report_status"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="status"><option>reviewing</option><option>substantiated</option><option>unsubstantiated</option><option>appealed</option><option>closed</option></select><button>Save</button></form></td></tr><?php endforeach;?><?php if(!$reports):?><tr><td colspan="5">No safety reports have been submitted.</td></tr><?php endif;?></tbody></table></div></section></main><script>
